package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var srId string
var srSales decimal.Decimal

var tierLimit [5]decimal.Decimal
var tierRate [5]decimal.Decimal

var scanner *bufio.Scanner
var salesFile *os.File
var inputDone bool = false

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatSalesComm(d decimal.Decimal) string {
	scaled := d.Truncate(2).Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	frac := scaled % 100
	intPart := (scaled / 100) % 1000000
	digits := fmt.Sprintf("%06d", intPart)
	firstNZ := -1
	for i := 0; i < 6; i++ {
		if digits[i] != '0' {
			firstNZ = i
			break
		}
	}
	intChars := make([]byte, 7)
	slot := 0
	for p := 0; p < 7; p++ {
		if p == 3 {
			if firstNZ != -1 && firstNZ <= 2 {
				intChars[p] = ','
			} else {
				intChars[p] = ' '
			}
		} else {
			ch := digits[slot]
			suppressed := false
			if p == 6 {
				suppressed = false
			} else {
				if firstNZ == -1 {
					suppressed = true
				} else if slot < firstNZ {
					suppressed = true
				}
			}
			if suppressed {
				intChars[p] = ' '
			} else {
				intChars[p] = ch
			}
			slot++
		}
	}
	fracStr := fmt.Sprintf("%02d", frac)
	return string(intChars) + "." + fracStr
}

func formatTotal(d decimal.Decimal) string {
	scaled := d.Truncate(2).Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	frac := scaled % 100
	intPart := (scaled / 100) % 1000000000
	digits := fmt.Sprintf("%09d", intPart)
	firstNZ := -1
	for i := 0; i < 9; i++ {
		if digits[i] != '0' {
			firstNZ = i
			break
		}
	}
	intChars := make([]byte, 11)
	slot := 0
	for p := 0; p < 11; p++ {
		if p == 3 {
			if firstNZ != -1 && firstNZ <= 2 {
				intChars[p] = ','
			} else {
				intChars[p] = ' '
			}
		} else if p == 7 {
			if firstNZ != -1 && firstNZ <= 5 {
				intChars[p] = ','
			} else {
				intChars[p] = ' '
			}
		} else {
			ch := digits[slot]
			suppressed := false
			if p == 10 {
				suppressed = false
			} else {
				if firstNZ == -1 {
					suppressed = true
				} else if slot < firstNZ {
					suppressed = true
				}
			}
			if suppressed {
				intChars[p] = ' '
			} else {
				intChars[p] = ch
			}
			slot++
		}
	}
	fracStr := fmt.Sprintf("%02d", frac)
	return string(intChars) + "." + fracStr
}

func formatRate(d decimal.Decimal) string {
	scaled := d.Truncate(2).Shift(2).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	frac := scaled % 100
	if frac < 0 {
		frac = -frac
	}
	intPart := (scaled / 100) % 10
	if intPart < 0 {
		intPart = -intPart
	}
	return fmt.Sprintf("%d.%02d", intPart, frac)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseSalesField(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	neg := false
	if strings.HasPrefix(t, "-") || strings.HasPrefix(t, "+") {
		if strings.HasPrefix(t, "-") {
			neg = true
		}
		t = t[1:]
	}
	// keep only digits
	digits := ""
	for _, c := range t {
		if c >= '0' && c <= '9' {
			digits += string(c)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	// strip leading zeros for big int parsing? use decimal
	var n int64 = 0
	for _, c := range digits {
		n = n*10 + int64(c-'0')
		// For very large, still fits in 8 digits; no overflow
	}
	d := decimal.New(n, -2)
	if neg {
		d = d.Neg()
	}
	return d
}

func INITPARA() {
	tierLimit[1] = decimal.New(100000, -2)
	tierRate[1] = decimal.New(250, -2)
	tierLimit[2] = decimal.New(500000, -2)
	tierRate[2] = decimal.New(400, -2)
	tierLimit[3] = decimal.New(2000000, -2)
	tierRate[3] = decimal.New(550, -2)
	tierLimit[4] = decimal.New(99999999, -2)
	tierRate[4] = decimal.New(725, -2)
}

func READPARA() {
	if scanner.Scan() {
		line := scanner.Text()
		// scanner strips \r already (ScanLines strips \r)
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		}
		if len(line) > 12 {
			line = line[:12]
		}
		srId = line[0:4]
		srSales = parseSalesField(line[4:12])
		// truncate to PIC 9(6)V99 (keep low-order if overflow)
		// scaled mod 10^8
		sc := srSales.Truncate(2).Shift(2).IntPart()
		mod := pow10(8)
		// keep low-order digits preserving sign? assume positive
		if sc >= mod || sc <= -mod {
			sc = sc % mod
			srSales = decimal.New(sc, -2)
		}
	} else {
		inputDone = true
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		if srSales.Cmp(tierLimit[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
	}
	prod := srSales.Mul(tierRate[WsTier])
	q := prod.Shift(-2)
	rounded := q.Round(2)
	// store into PIC 9(6)V99 with truncation of high-order
	sc := rounded.Shift(2).IntPart()
	mod := pow10(8)
	if sc >= mod || sc <= -mod {
		sc = sc % mod
		rounded = decimal.New(sc, -2)
	}
	WsComm = rounded
	WsTotal = WsTotal.Add(WsComm)
	// fit total to 9(9)V99
	tsc := WsTotal.Shift(2).IntPart()
	tmod := pow10(11)
	if tsc >= tmod || tsc <= -tmod {
		tsc = tsc % tmod
		WsTotal = decimal.New(tsc, -2)
	}
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatSalesComm(srSales)
	WsRateEd = formatRate(tierRate[WsTier])
	WsCommEd = formatSalesComm(WsComm)
	tierStr := fmt.Sprintf("%01d", WsTier)
	fmt.Printf("%s T%s %s %s%% %s\n", padRight(srId, 4), tierStr, WsSalesEd, WsRateEd, WsCommEd)
	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatTotal(WsTotal)
	countStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	INITPARA()
	var err error
	salesFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer salesFile.Close()
	scanner = bufio.NewScanner(salesFile)
	// allow long lines
	scanner.Buffer(make([]byte, 1024), 1024*1024)
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	// CLOSE SALES-FILE
	// scanner errors ignored
	SUMMARYPARA()
}
